import React,{useEffect,useMemo,useState} from "react";
import { getAdminUsers } from "../auth/adminUsersApi";
import {Activity,BarChart3,History,MessageSquare,Play,Save,Settings2,ShieldCheck,Ticket,Users,Package,LockKeyhole,HelpCircle,Search,Bell,ClipboardCheck,Download} from "lucide-react";
import {addApprovalComment,canFuel,createAutomaticFuelTicket,getApprovalComments,getApprovalSla,getContractRules,getCustomerTimeline,getDailyFuelSummary,decideRollbackRequest,getEscalationQueue,getFuelSourceHealth,getRolePermissions,getRollbackRequests,getRuleHistory,saveRolePermissions,saveVersionedContractRule,simulateFuelPrice} from "./fuelEscalationEngineV3";
import {ACTIONS,ACTION_LABELS,acquireApprovalLock,explainPrice,getApprovalLock,getCustomerConflict,getEffectiveUserPermissions,getOperationPriorities,getOrCreatePackage,getPackage,getTariffAtDate,releaseApprovalLock,saveUserPermissions,thresholdProgress,getFuelNotificationPreferences,saveFuelNotificationPreferences,getFuelDataQuality,getFuelReadinessChecklist,buildFuelAuditCsv} from "./fuelEscalationEngineV4";
import "./YakitYonetimMerkeziV3.css";
const tabs=[["overview","Operasyon Merkezi",Activity],["packages","Güncelleme Paketleri",Package],["rules","Kural Yönetimi",Settings2],["roles","Yetkiler",Users],["comments","Onay Yorumları",MessageSquare],["simulation","Simülasyon",Play],["timeline","Müşteri Timeline",History],["why","Neden Bu Fiyat?",Search],["time","Zaman Makinesi",History],["trend","Fiyat Grafiği",BarChart3],["health","Sistem Sağlığı",ShieldCheck],["control","Kontrol & Tercihler",ClipboardCheck]];
const fmt=n=>Number(n||0).toLocaleString("tr-TR",{maximumFractionDigits:2});
export default function YakitYonetimMerkeziV3(){const[,refresh]=useState(0),[tab,setTab]=useState("overview"),[customer,setCustomer]=useState("BİM"),[sim,setSim]=useState("105"),[simRows,setSimRows]=useState([]),[comment,setComment]=useState(""); const rules=getContractRules(), queue=getEscalationQueue(), summary=getDailyFuelSummary(); useEffect(()=>{const f=()=>refresh(x=>x+1);window.addEventListener("odak-escalation-changed",f);return()=>window.removeEventListener("odak-escalation-changed",f)},[]); const pending=queue.filter(x=>["pending","postponed","suspicious"].includes(x.status)); const delayed=pending.filter(x=>getApprovalSla(x).level==="critical").length; const active=queue.find(x=>x.customer===customer); const timeline=getCustomerTimeline(customer).slice(0,30); const history=getRuleHistory().filter(x=>x.customer===customer).slice(0,8); const health=Object.values(getFuelSourceHealth()); const rollback=getRollbackRequests();
return <main className="fuel-v3"><header className="v3-hero"><div><small>YAKIT YÖNETİM MERKEZİ V3</small><h1>Kontrol, onay ve otomasyon tek ekranda</h1><p>Kural, onay, paket, yetki, simülasyon, fiyat geçmişi ve otomasyon tek merkezde. Aşağıdaki kısa açıklamalar yalnızca bu yakıt ekranında görünür.</p></div><ShieldCheck/></header><FuelGuide tab={tab}/><nav className="v3-tabs">{tabs.map(([k,l,I])=><button className={tab===k?"active":""} onClick={()=>setTab(k)} key={k}><I size={17}/>{l}</button>)}</nav>
{tab==="overview"&&<><ThresholdCards rules={rules}/><section className="v3-kpis"><article><b>{pending.length}</b><span>Bekleyen onay</span></article><article><b>{delayed}</b><span>SLA gecikmiş</span></article><article><b>{summary.approved}</b><span>Bugün onaylanan</span></article><article><b>{summary.affected}</b><span>Etkilenen fiyat alanı</span></article></section><section className="v3-grid"><OperationPriorities/><article className="v3-panel"><h3>Bugün yapılacaklar</h3>{pending.slice(0,6).map(r=>{const s=getApprovalSla(r);return <div className="v3-row" key={r.id}><span><b>{r.customer}</b><small>{r.id}</small></span><em className={s.level}>{s.label} · {fmt(s.hours)} saat</em></div>})}{!pending.length&&<p>Bekleyen onay bulunmuyor.</p>}</article><article className="v3-panel"><h3>Günlük yönetici özeti</h3><p>{summary.checked} müşteri kuralı kontrol altında.</p><div className="v3-summary"><span>Oluşan <b>{summary.created}</b></span><span>Bekleyen <b>{summary.pending}</b></span><span>Onaylanan <b>{summary.approved}</b></span><span>Reddedilen <b>{summary.rejected}</b></span></div></article><article className="v3-panel"><h3>Geri alma onayları</h3>{rollback.slice(0,5).map(x=><div className="v3-row" key={x.id}><span><b>{x.customer}</b><small>{x.reason||"Geri alma talebi"}</small></span><span className="v3-rb"><em>{x.status}</em>{x.status==="pending"&&canFuel("rollback")&&<><button onClick={()=>{decideRollbackRequest(x.id,true);refresh(v=>v+1)}}>Onayla</button><button onClick={()=>{decideRollbackRequest(x.id,false);refresh(v=>v+1)}}>Reddet</button></>}</span></div>)}{!rollback.length&&<p>Geri alma talebi yok.</p>}</article></section></>}
{tab==="rules"&&<RuleEditor rules={rules} customer={customer} setCustomer={setCustomer} history={history} refresh={refresh}/>} 
{tab==="packages"&&<PackageCenter queue={queue} customer={customer} setCustomer={setCustomer}/>}
{tab==="roles"&&<RealUserPermissions refresh={refresh}/>} 
{tab==="comments"&&<section className="v3-panel"><h3>Onay yorumları</h3><select value={customer} onChange={e=>setCustomer(e.target.value)}>{Object.keys(rules).map(x=><option key={x}>{x}</option>)}</select>{active?<><div className="v3-comments">{getApprovalComments(active.id).map(c=><div key={c.id}><b>{c.actor}</b><span>{c.text}</span><small>{new Date(c.created_at).toLocaleString("tr-TR")}</small></div>)}</div><div className="v3-compose"><input value={comment} onChange={e=>setComment(e.target.value)} placeholder="Onay hakkında not yazın..."/><button onClick={()=>{addApprovalComment(active.id,comment);setComment("");refresh(x=>x+1)}}>Yorum ekle</button></div></>:<p>Bu müşteri için onay kaydı yok.</p>}</section>}
{tab==="simulation"&&<section className="v3-panel"><h3>Yakıt fiyat simülasyonu</h3><p>Gerçek tarifeleri değiştirmeden olası yakıt fiyatının müşteri kurallarına etkisini hesaplar.</p><div className="v3-compose"><input type="number" value={sim} onChange={e=>setSim(e.target.value)} placeholder="Yeni motorin fiyatı"/><button onClick={()=>setSimRows(simulateFuelPrice(sim))}><Play size={16}/> Simülasyonu çalıştır</button></div><div className="v3-table"><table><thead><tr><th>Müşteri</th><th>Yakıt değişimi</th><th>Eşik</th><th>Tarife etkisi</th><th>Durum</th></tr></thead><tbody>{simRows.map(r=><tr key={r.customer}><td>{r.customer}</td><td>{r.ok?`%${fmt(r.fuelChange)}`:"—"}</td><td>{r.ok?`%${r.rule.threshold}`:"—"}</td><td>{r.ok?`%${fmt(r.appliedRate)}`:"—"}</td><td>{r.ok?(r.thresholdPassed?"Eşik aşılır":"İşlem yok"):r.reason}</td></tr>)}</tbody></table></div></section>}
{tab==="why"&&<WhyPrice customer={customer} setCustomer={setCustomer} rules={rules}/>}
{tab==="time"&&<TimeMachine customer={customer} setCustomer={setCustomer} rules={rules}/>}
{tab==="timeline"&&<section className="v3-panel"><h3>Müşteri zaman çizelgesi</h3><select value={customer} onChange={e=>setCustomer(e.target.value)}>{Object.keys(rules).map(x=><option key={x}>{x}</option>)}</select><div className="v3-timeline">{timeline.map(x=><div key={x.id}><i/><span><b>{x.event}</b><small>{x.actor} · {new Date(x.created_at).toLocaleString("tr-TR")}</small></span></div>)}{!timeline.length&&<p>Henüz aktivite yok.</p>}</div></section>}

{tab==="trend"&&<section className="v3-panel"><h3>Yakıt fiyat hareketi</h3><p>Onay kayıtlarındaki referans yakıt fiyatlarından oluşturulan geçmiş görünüm.</p><select value={customer} onChange={e=>setCustomer(e.target.value)}>{Object.keys(rules).map(x=><option key={x}>{x}</option>)}</select><FuelTrend rows={queue.filter(x=>x.customer===customer)}/></section>}
{tab==="control"&&<ControlCenter/>}
{tab==="health"&&<section className="v3-grid"><article className="v3-panel wide"><h3>Otomasyon sağlık merkezi</h3>{health.map(h=><div className="v3-health" key={h.source}><span className={h.status}/><div><b>{h.source}</b><small>{h.message||h.status} {h.checked_at?`· ${new Date(h.checked_at).toLocaleString("tr-TR")}`:""}</small></div><button onClick={()=>createAutomaticFuelTicket({title:`${h.source} yakıt kaynağı kontrolü`,description:`${h.source}: ${h.message||h.status}`})}><Ticket size={15}/> Ticket</button></div>)}</article></section>}
</main>}
function FuelTrend({rows}){const data=useMemo(()=>rows.flatMap(r=>[{t:r.created_at,v:Number(r.oldFuel)},{t:r.created_at,v:Number(r.newFuel)}]).filter(x=>x.v>0).sort((a,b)=>new Date(a.t)-new Date(b.t)).slice(-30),[rows]); if(data.length<2)return <p>Grafik için yeterli fiyat geçmişi yok.</p>; const min=Math.min(...data.map(x=>x.v)),max=Math.max(...data.map(x=>x.v)),span=max-min||1,pts=data.map((x,i)=>`${20+i*(760/(data.length-1))},${190-((x.v-min)/span)*150}`).join(" "); return <div className="v3-chart"><svg viewBox="0 0 800 220" role="img" aria-label="Yakıt fiyat grafiği"><polyline points={pts} fill="none" stroke="currentColor" strokeWidth="4" strokeLinejoin="round"/>{data.map((x,i)=><circle key={i} cx={20+i*(760/(data.length-1))} cy={190-((x.v-min)/span)*150} r="5"><title>{new Date(x.t).toLocaleDateString("tr-TR")} · {fmt(x.v)} TL</title></circle>)}</svg><div><span>Min: {fmt(min)} TL</span><span>Max: {fmt(max)} TL</span><span>Son: {fmt(data[data.length-1].v)} TL</span></div></div>}
function RuleEditor({rules,customer,setCustomer,history,refresh}){const rule=rules[customer], [form,setForm]=useState(rule); useEffect(()=>setForm(rules[customer]),[customer]); if(!canFuel("rules"))return <section className="v3-panel"><h3>Kural Yönetimi</h3><p>Bu işlem için yönetici yetkisi gerekiyor.</p></section>; return <section className="v3-grid"><article className="v3-panel"><h3>Sözleşme / yakıt kuralı</h3><select value={customer} onChange={e=>setCustomer(e.target.value)}>{Object.keys(rules).map(x=><option key={x}>{x}</option>)}</select><div className="v3-form"><label>Eşik %<input type="number" value={form.threshold} onChange={e=>setForm({...form,threshold:Number(e.target.value)})}/></label><label>Yansıtma %<input type="number" value={form.factor} onChange={e=>setForm({...form,factor:Number(e.target.value)})}/></label><label>Çalışma modu<select value={form.mode} onChange={e=>setForm({...form,mode:e.target.value})}><option value="approval">Onay bekle</option><option value="auto">Otomatik uygula</option><option value="notify">Sadece bildir</option></select></label><label>Referans kaynak<input value={form.provider} onChange={e=>setForm({...form,provider:e.target.value})}/></label><label>Lokasyon<input value={form.location} onChange={e=>setForm({...form,location:e.target.value})}/></label></div><button className="v3-primary" onClick={()=>{saveVersionedContractRule(customer,form,"Yönetim Merkezi V3 üzerinden güncellendi");refresh(x=>x+1)}}><Save size={16}/> Yeni versiyon olarak kaydet</button></article><article className="v3-panel"><h3>Kural geçmişi</h3>{history.map(h=><div className="v3-row" key={h.id}><span><b>v{h.version} · {h.reason}</b><small>%{h.before?.threshold} / %{h.before?.factor} → %{h.after?.threshold} / %{h.after?.factor}</small></span><em>{h.actor}</em></div>)}{!history.length&&<p>Henüz kural değişikliği yok.</p>}</article></section>}
function RoleEditor({refresh}){const [roles,setRoles]=useState(getRolePermissions()); const actions=["view","submit","approve","reject","rules","rollback"]; return <section className="v3-panel"><h3>Kullanıcı yetkilendirme</h3><p>Yetkiler arayüzde görünürlüğü kontrol eder; gerçek üretim ortamında aynı kontroller backend API tarafında da uygulanmalıdır.</p><div className="v3-table"><table><thead><tr><th>Rol</th>{actions.map(a=><th key={a}>{a}</th>)}</tr></thead><tbody>{Object.entries(roles).map(([role,perms])=><tr key={role}><td><b>{role}</b></td>{actions.map(a=><td key={a}><input type="checkbox" checked={perms.includes(a)} onChange={e=>setRoles({...roles,[role]:e.target.checked?[...perms,a]:perms.filter(x=>x!==a)})}/></td>)}</tr>)}</tbody></table></div><button className="v3-primary" onClick={()=>{saveRolePermissions(roles);refresh(x=>x+1)}}><Save size={16}/> Yetkileri kaydet</button></section>}

function FuelGuide({tab}){const map={overview:["Operasyon Merkezi","Öncelikli işleri, eşiğe yaklaşan müşterileri ve geciken onayları buradan takip edin."],packages:["Güncelleme Paketleri","Her yakıt değişikliği tek bir PKT numarasıyla izlenir. Referans yakıt fiyatı paket oluşturulduğu anda sabitlenir."],rules:["Kural Yönetimi","Müşteri eşik, yansıtma, kaynak ve çalışma modunu değiştirin. Her kayıt yeni versiyon oluşturur."],roles:["Gerçek Kullanıcı Yetkileri","Supabase Login tablosundaki gerçek kullanıcılar listelenir. Yetkiyi kullanıcı bazında değiştirebilirsiniz."],comments:["Onay Yorumları","Bir onay üzerinde ekip içi not bırakın; kararın neden verildiği daha sonra görülebilir."],simulation:["Simülasyon","Gerçek tarifeye dokunmadan farklı motorin fiyatlarının müşteri kurallarına etkisini test edin."],timeline:["Müşteri Timeline","Müşteriye ait onay, tarife ve audit hareketlerini kronolojik inceleyin."],why:["Neden Bu Fiyat?","Bir müşterinin tarifesini etkileyen geçmiş eskalasyon zincirini adım adım açıklayın."],time:["Zaman Makinesi","Geçmiş bir tarihi seçip o tarihte geçerli son snapshot verisini görüntüleyin."],trend:["Fiyat Grafiği","Onay kayıtlarında kullanılan referans fiyatların tarihsel hareketini görün."],health:["Sistem Sağlığı","Yakıt kaynakları ve otomasyon durumunu izleyin; sorun için tek tıkla ticket açın."],control:["Kontrol & Tercihler","Veri kalitesini, devreye alma kontrol listesini, bildirim tercihlerini ve denetim çıktısını tek yerden yönetin."]};const x=map[tab]||map.overview;return <div className="v4-guide"><div className="v4-tip"><b><HelpCircle size={13}/> {x[0]}</b><span>{x[1]}</span></div><div className="v4-tip"><b>Güvenli kullanım</b><span>Onay öncesinde paket numarası, sabitlenen referans fiyat ve değişecek kayıt özetini kontrol edin.</span></div><div className="v4-tip"><b>İpucu</b><span>Turuncu/kırmızı göstergeler işlem önceliğini anlatır; tek başına otomatik tarife değişikliği yapmaz.</span></div></div>}
function ThresholdCards({rules}){return <section className="v4-customer-grid">{Object.keys(rules).map(c=>{const p=thresholdProgress(c);return <article className={`v4-customer ${p.state}`} key={c}><b>{c}</b><small>Mevcut değişim %{fmt(p.current)} · Eşik %{fmt(p.threshold)}</small><div className="v4-progress"><i style={{width:`${p.percent}%`}}/></div><small>{p.state==='passed'?'Eşik aşıldı':p.state==='near'?`Eşiğe ${fmt(p.remaining)} puan kaldı`:'Eşik altında'}</small></article>})}</section>}
function OperationPriorities(){const rows=getOperationPriorities();return <article className="v3-panel"><h3>Öncelikli işlemler</h3>{rows.slice(0,8).map(x=><div className={`v4-priority ${x.severity}`} key={x.id}><i/><span><b>{x.title}</b><small>{x.detail}</small></span></div>)}{!rows.length&&<p>Şu anda müdahale gerektiren yakıt işlemi yok.</p>}</article>}
function PackageCenter({queue,customer,setCustomer}){const rows=queue.map(r=>({r,p:getOrCreatePackage(r),conf:getCustomerConflict(r.customer),lock:getApprovalLock(r.id)}));return <section className="v3-panel"><h3>Tarife Güncelleme Paketleri</h3><div className="v4-help">PKT numarası onay, audit, rollback ve referans fiyatı aynı işlem altında toplar. Paket içindeki yakıt fiyatı sonradan API fiyatı değişse bile değişmez.</div><div className="v3-table"><table><thead><tr><th>Paket</th><th>Müşteri</th><th>Referans yakıt</th><th>Tarife etkisi</th><th>Kayıt</th><th>Durum</th><th>Çakışma / Kilit</th></tr></thead><tbody>{rows.map(({r,p,conf,lock})=><tr key={r.id}><td><b>{p?.id}</b><br/><small>{r.id}</small></td><td>{r.customer}</td><td>{fmt(p?.oldFuel)} → <b>{fmt(p?.lockedFuel)} TL</b></td><td>%{fmt(p?.appliedRate)}</td><td>{r.affectedRoutes||0}</td><td>{r.status}</td><td>{conf.hasConflict?<span className="v4-badge">{conf.count} aktif işlem</span>:lock?<span className="v4-badge"><LockKeyhole size={11}/> {lock.user}</span>:<LockButtons id={r.id}/>}</td></tr>)}</tbody></table></div></section>}
function LockButtons({id}){const[,r]=useState(0),lock=getApprovalLock(id);if(lock)return <div className="v4-lock">{lock.user} inceliyor · {new Date(lock.expires_at).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'})}</div>;return <div className="v4-actions"><button onClick={()=>{acquireApprovalLock(id);r(x=>x+1)}}><LockKeyhole size={12}/> İncelemeyi kilitle</button><button onClick={()=>{releaseApprovalLock(id);r(x=>x+1)}}>Kilidi bırak</button></div>}
function RealUserPermissions({refresh}){const [users,setUsers]=useState([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),rolePerms=getRolePermissions();useEffect(()=>{let alive=true;(async()=>{setLoading(true);let data=[];let error=null;try{    data=await getAdminUsers();}catch(err){    error=err;}if(!alive)return;if(error){setError(error.message);setUsers([])}else setUsers(data||[]);setLoading(false)})();return()=>{alive=false}},[]);if(loading)return <section className="v3-panel v4-users-loading">Gerçek kullanıcılar yükleniyor...</section>;return <section className="v3-panel"><h3>Gerçek kullanıcı yetkileri</h3><div className="v4-help">Bu liste güvenli yönetici API'si üzerinden gelir. Kullanıcı bazlı seçim yapıldığında rol varsayılanının üzerine yazılır. Güvenlik için aynı izinler backend/API tarafında da kontrol edilmelidir.</div>{error&&<p>{error}</p>}<div className="v3-table"><table><thead><tr><th>Kullanıcı</th><th>Rol</th>{ACTIONS.map(a=><th key={a}>{ACTION_LABELS[a]}</th>)}</tr></thead><tbody>{users.map(u=>{const perms=getEffectiveUserPermissions(u,rolePerms);return <UserPermissionRow key={u.id} user={u} initial={perms} onSave={()=>refresh(x=>x+1)}/>})}</tbody></table></div></section>}
function UserPermissionRow({user,initial,onSave}){const [perms,setPerms]=useState(initial);return <tr><td><div className="v4-user"><span className="v4-avatar">{String(user.kullanici||user.kullanici_adi||'?').charAt(0).toUpperCase()}</span><span><b>{user.kullanici||'İsimsiz kullanıcı'}</b><small>{user.kullanici_adi}</small></span></div></td><td><span className="v4-badge">{user.rol||'kullanici'}</span></td>{ACTIONS.map(a=><td key={a}><input type="checkbox" checked={perms.includes(a)} onChange={e=>setPerms(e.target.checked?[...new Set([...perms,a])]:perms.filter(x=>x!==a))}/></td>)}<td><button className="v3-primary" onClick={()=>{saveUserPermissions(user.id,perms);onSave()}}>Kaydet</button></td></tr>}
function WhyPrice({customer,setCustomer,rules}){const rows=explainPrice(customer);return <section className="v3-panel"><h3>Neden bu fiyat?</h3><p>Tarifeyi etkileyen yakıt eskalasyonlarını başlangıçtan bugüne açıklayan iz.</p><select value={customer} onChange={e=>setCustomer(e.target.value)}>{Object.keys(rules).map(x=><option key={x}>{x}</option>)}</select><div className="v3-timeline">{rows.map(x=><div key={x.escalationId}><i/><span><b>{new Date(x.date).toLocaleDateString('tr-TR')} · Tarife %{fmt(x.rate)} değişti</b><small>Yakıt {fmt(x.fuelBefore)} → {fmt(x.fuelAfter)} TL · {x.affected} fiyat alanı · {x.actor}</small></span></div>)}{!rows.length&&<p>Bu müşteri için uygulanmış eskalasyon snapshot'ı yok.</p>}</div></section>}
function TimeMachine({customer,setCustomer,rules}){const [date,setDate]=useState(new Date().toISOString().slice(0,10)),[result,setResult]=useState(null);return <section className="v3-panel"><h3>Tarife Zaman Makinesi</h3><div className="v4-help">Seçilen tarihten önceki en son uygulanmış snapshot bulunur. Bu ekran yalnızca görüntüler; mevcut tarifeyi değiştirmez.</div><div className="v4-time"><div className="v3-form"><label>Müşteri<select value={customer} onChange={e=>setCustomer(e.target.value)}>{Object.keys(rules).map(x=><option key={x}>{x}</option>)}</select></label><label>Tarih<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><button className="v3-primary" onClick={()=>setResult(getTariffAtDate(customer,date+'T23:59:59'))}>O tarihteki tarifeyi getir</button></div><div>{result?<><p><b>Snapshot:</b> {result.snapshotId} · {new Date(result.date).toLocaleString('tr-TR')} · {result.actor}</p><pre className="v4-json">{JSON.stringify(result.data,null,2)}</pre></>:<p>Tarih seçip sorgulayın.</p>}</div></div></section>}

function ControlCenter(){const [prefs,setPrefs]=useState(getFuelNotificationPreferences()),quality=getFuelDataQuality(),check=getFuelReadinessChecklist();const download=()=>{const blob=new Blob(['\ufeff'+buildFuelAuditCsv()],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`yakit-denetim-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(url)};return <section className="v3-grid"><article className="v3-panel"><h3>Devreye alma kontrol listesi</h3><div className="v4-help">Otomasyonu aktif kullanmadan önce temel kontrolleri burada tek bakışta doğrulayın.</div>{check.map(x=><div className="v3-row" key={x.id}><span><b>{x.ok?'✓':'!'} {x.label}</b><small>{x.detail}</small></span><em className={x.ok?'safe':'critical'}>{x.ok?'Hazır':'Kontrol'}</em></div>)}</article><article className="v3-panel"><h3>Veri kalite kontrolü</h3><p><b>{quality.checked}</b> müşteri kontrol edildi · <b>{quality.critical}</b> kritik · <b>{quality.warning}</b> uyarı</p>{quality.issues.slice(0,8).map((x,i)=><div className={`v4-priority ${x.level}`} key={i}><i/><span><b>{x.customer} · {x.title}</b><small>{x.detail}</small></span></div>)}{!quality.issues.length&&<p>✓ Kural ve temel yakıt verilerinde sorun görünmüyor.</p>}</article><article className="v3-panel"><h3><Bell size={17}/> Bildirim tercihleri</h3><div className="v4-help">Bu ayarlar yalnızca yakıt yönetimi bildirimlerini kapsar.</div>{[['inApp','Sistem içi bildirim'],['email','E-posta bildirimi'],['approval','Onay bekliyor uyarıları'],['threshold','Eşiğe yaklaşıyor uyarıları'],['health','Kaynak / otomasyon hataları'],['dailySummary','Günlük yönetici özeti']].map(([k,l])=><label className="v5-pref" key={k}><span>{l}</span><input type="checkbox" checked={!!prefs[k]} onChange={e=>setPrefs({...prefs,[k]:e.target.checked})}/></label>)}<button className="v3-primary" onClick={()=>saveFuelNotificationPreferences(prefs)}><Save size={15}/> Tercihleri kaydet</button></article><article className="v3-panel"><h3>Denetim ve dışa aktarım</h3><p>Yakıt yönetimi audit geçmişini tarih, müşteri, olay ve kullanıcı bilgileriyle CSV olarak alın.</p><button className="v3-primary" onClick={download}><Download size={15}/> Denetim CSV indir</button><div className="v4-help">İpucu: Onay veya tarife uyuşmazlığı araştırırken paket numarasıyla birlikte bu çıktıyı kullanın.</div></article></section>}
